insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('1', '1', '1', '{"mrr_INR": 0, "has_idea": true, "funding_stage": "none", "has_prototype": false, "paying_customers": 0}', '{"has_prototype": true, "paying_customers": 0, "customer_interviews_min": 10}', 'SaaS Stage 1 (Ideation): Founder has a software idea but no prototype. Exit when a working prototype exists and at least 10 customer interviews completed. Revenue is not expected here.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('2', '1', '2', '{"funding_stage": "pre-seed or none", "has_prototype": true, "paying_customers": 0, "customer_interviews_min": 10}', '{"has_mvp": true, "mrr_INR": 0, "paying_customers": 0, "active_beta_users_min": 1}', 'SaaS Stage 2 (Validation): Prototype tested with real users. Exit when MVP is live and at least one active beta user is using it. Still pre-revenue — validation focus only.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('3', '1', '3', '{"has_mvp": true, "mrr_INR": 0, "funding_stage": "seed or none", "active_beta_users_min": 1}', '{"mrr_INR_max": 50000, "paying_customers_max": 5, "monthly_churn_pct_max": 10}', 'SaaS Stage 3 (Prototype/MVP): MVP live with first users. Exit when MRR crosses Rs 50,000 with at least 3 paying customers and monthly churn below 10%. Focus is on PMF signals.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('4', '1', '4', '{"mrr_INR_min": 50000, "paying_customers_min": 3, "monthly_churn_pct_max": 10, "has_repeatable_sales_process": false}', '{"mrr_INR_max": 500000, "paying_customers_max": 50, "mom_growth_rate_min_pct": 15}', 'SaaS Stage 4 (Early Traction): First paying customers, MRR Rs 50k to Rs 5L. Exit when MRR crosses Rs 5,00,000 with 15%+ month-on-month growth. Sales process starting to repeat.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('5', '1', '5', '{"arr_INR_min": 6000000, "mrr_INR_min": 500000, "funding_stage": "Series A or seed", "ltv_cac_ratio_min": 1.5, "paying_customers_min": 50}', '{"arr_INR_max": 60000000, "nrr_min_pct": 100, "monthly_churn_max_pct": 3}', 'SaaS Stage 5 (Growth/Scaling): MRR Rs 5L to ARR Rs 6 Crore. Exit when ARR crosses Rs 6 Crore with NRR above 100% and monthly churn below 3%. Unit economics must be understood by now.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('6', '1', '6', '{"arr_INR_min": 60000000, "nrr_min_pct": 100, "funding_stage": "Series A or B", "monthly_churn_max_pct": 3, "has_formal_departments": true}', '{"arr_INR_max": 600000000, "gross_margin_min_pct": 65, "international_markets_min": 1}', 'SaaS Stage 6 (Expansion): ARR Rs 6 Crore to Rs 60 Crore. Formal team structure in place. New markets or enterprise segment being entered. Gross margin must be above 65%.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('7', '1', '7', '{"arr_INR_min": 600000000, "nrr_min_pct": 110, "funding_stage": "Series B or C", "gross_margin_min_pct": 65, "has_professional_management": true}', '{"arr_INR_min": 2000000000, "ipo_ready_or_acquisition_initiated": true}', 'SaaS Stage 7 (Maturity): ARR Rs 60 Crore and above. NRR above 110%, professional management in place. Exit when IPO process initiated or serious acquisition conversations begin above Rs 200 Crore ARR.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('8', '1', '8', '{"exit_type": "acquisition or IPO", "arr_INR_min": 2000000000, "exit_process_initiated": true}', '{"exit_completed": true}', 'SaaS Stage 8 (Exit): Formal exit process underway — acquisition due diligence or IPO roadshow. Business above Rs 200 Crore ARR. Founder role transitioning to new structure.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('9', '2', '1', '{"has_idea": true, "funding_stage": "none", "has_prototype": false, "paying_clients": 0, "monthly_billing_INR": 0}', '{"service_offering_defined": true, "first_client_conversation_initiated": true}', 'Services Stage 1 (Ideation): Founder has a consulting or service concept but no clients. Exit when service offering is clearly defined and first client conversations have begun.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('10', '2', '2', '{"paying_clients": 0, "service_offering_defined": true, "first_client_conversation_initiated": true}', '{"paying_clients_min": 1, "monthly_billing_INR_min": 50000}', 'Services Stage 2 (Validation): Service defined, conversations happening. Exit when first paying client is secured and monthly billing crosses Rs 50,000. Proof that someone will pay for the service.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('11', '2', '3', '{"funding_stage": "none or bootstrapped", "paying_clients_min": 1, "monthly_billing_INR_min": 50000}', '{"paying_clients_max": 3, "monthly_billing_INR_max": 200000, "client_concentration_max_pct": 80}', 'Services Stage 3 (Prototype/MVP): 1 to 3 paying clients, billing Rs 50k to Rs 2L per month. Founder doing most delivery personally. Exit when billing crosses Rs 2L with at least 3 clients and no single client above 80% of revenue.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('12', '2', '4', '{"paying_clients_min": 3, "monthly_billing_INR_min": 200000, "client_concentration_max_pct": 80, "has_at_least_one_team_member": true}', '{"paying_clients_max": 10, "monthly_billing_INR_max": 1000000, "client_concentration_max_pct": 50}', 'Services Stage 4 (Early Traction): Billing Rs 2L to Rs 10L per month, 3 to 10 clients. First team member hired. No single client above 50% of revenue. Referrals starting to come in.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('13', '2', '5', '{"paying_clients_min": 10, "gross_margin_min_pct": 40, "has_retainer_revenue": true, "monthly_billing_INR_min": 1000000, "client_concentration_max_pct": 50}', '{"gross_margin_min_pct": 45, "annual_billing_INR_max": 50000000, "retainer_revenue_min_pct": 30}', 'Services Stage 5 (Growth/Scaling): Monthly billing Rs 10L to annual Rs 5 Crore. Retainer revenue above 30% of total. Gross margin above 40%. Founder starting to step back from full delivery.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('14', '2', '6', '{"has_team_leads": true, "gross_margin_min_pct": 45, "annual_billing_INR_min": 50000000, "retainer_revenue_min_pct": 30}', '{"client_count_min": 20, "annual_billing_INR_max": 200000000, "revenue_per_employee_INR_min": 1500000}', 'Services Stage 6 (Expansion): Annual billing Rs 5 Crore to Rs 20 Crore. Team leads in place for key functions. Revenue per employee above Rs 15L per year. 20+ active clients.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('15', '2', '7', '{"gross_margin_min_pct": 45, "annual_billing_INR_min": 200000000, "has_professional_management": true, "revenue_per_employee_INR_min": 1500000}', '{"acquisition_initiated": true, "annual_billing_INR_min": 500000000}', 'Services Stage 7 (Maturity): Annual billing Rs 20 Crore and above. Professional management in place. Productised service lines exist. Exit when acquisition conversations or management buyout process begins above Rs 50 Crore billing.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('16', '2', '8', '{"exit_type": "acquisition or management buyout or merger", "annual_billing_INR_min": 500000000, "exit_process_initiated": true}', '{"exit_completed": true}', 'Services Stage 8 (Exit): Formal exit above Rs 50 Crore annual billing. Acquisition, merger, or management buyout in progress. Founder transitioning out of operational role.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('17', '3', '1', '{"gmv_INR": 0, "funding_stage": "none", "has_product_idea": true, "paying_customers": 0, "has_prototype_or_sample": false}', '{"supplier_identified": true, "has_physical_sample_or_prototype": true}', 'Manufacturing/D2C Stage 1 (Ideation): Physical product concept exists but no sample produced. Exit when a physical prototype or sample exists and at least one supplier has been identified.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('18', '3', '2', '{"paying_customers": 0, "has_physical_sample": true, "supplier_identified": true}', '{"monthly_gmv_INR_min": 50000, "first_sale_completed": true, "compliance_documentation_basic": true}', 'Manufacturing/D2C Stage 2 (Validation): Sample exists, supplier confirmed. Exit when first sale is completed, monthly GMV crosses Rs 50,000, and basic compliance documentation is in place.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('19', '3', '3', '{"funding_stage": "bootstrapped or none", "monthly_gmv_INR_min": 50000, "paying_customers_min": 1, "compliance_documentation_basic": true}', '{"monthly_gmv_INR_max": 500000, "return_rate_max_pct": 20, "repeat_purchase_rate_90day_pct_min": 15}', 'Manufacturing/D2C Stage 3 (Prototype/MVP): Monthly GMV Rs 50k to Rs 5L. First repeat customers appearing. Return rate below 20%. Working capital cycle being understood. Exit when GMV crosses Rs 5L with 15%+ 90-day repeat rate.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('20', '3', '4', '{"monthly_gmv_INR_min": 500000, "return_rate_max_pct": 20, "has_inventory_management": true, "repeat_purchase_rate_90day_pct_min": 15}', '{"monthly_gmv_INR_max": 3000000, "gross_margin_min_pct": 40, "working_capital_cycle_max_days": 90}', 'Manufacturing/D2C Stage 4 (Early Traction): Monthly GMV Rs 5L to Rs 30L. Gross margin above 40%. Working capital cycle managed below 90 days. Inventory management system in place.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('21', '3', '5', '{"funding_stage": "seed or bootstrapped", "monthly_gmv_INR_min": 3000000, "gross_margin_min_pct": 40, "working_capital_cycle_max_days": 90, "repeat_purchase_rate_90day_pct_min": 25}', '{"annual_gmv_INR_max": 500000000, "gross_margin_min_pct": 50, "marketplace_dependency_max_pct": 60}', 'Manufacturing/D2C Stage 5 (Growth/Scaling): Monthly GMV Rs 30L to annual Rs 50 Crore. Gross margin above 50%. No more than 60% GMV from any single marketplace. Supply chain diversification underway.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('22', '3', '6', '{"funding_stage": "Series A or above", "annual_gmv_INR_min": 500000000, "gross_margin_min_pct": 50, "has_own_brand_presence": true, "marketplace_dependency_max_pct": 60}', '{"annual_gmv_INR_max": 2000000000, "own_channel_revenue_pct_min": 30, "international_or_new_category": true}', 'Manufacturing/D2C Stage 6 (Expansion): Annual GMV Rs 50 Crore to Rs 200 Crore. Own channel contributing 30%+ of GMV. New product category or international market being entered.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('23', '3', '7', '{"annual_gmv_INR_min": 2000000000, "gross_margin_min_pct": 55, "has_professional_management": true, "own_channel_revenue_pct_min": 30}', '{"annual_gmv_INR_min": 5000000000, "ipo_ready_or_acquisition_initiated": true}', 'Manufacturing/D2C Stage 7 (Maturity): Annual GMV Rs 200 Crore and above. Strong brand, professional management, multiple channels. Exit process begins above Rs 500 Crore GMV.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('24', '3', '8', '{"exit_type": "acquisition or IPO or PE buyout", "annual_gmv_INR_min": 5000000000, "exit_process_initiated": true}', '{"exit_completed": true}', 'Manufacturing/D2C Stage 8 (Exit): Formal exit above Rs 500 Crore GMV. Acquisition by strategic buyer, PE buyout, or IPO in process. Founder transitioning from operations.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('25', '4', '1', '{"active_donors": 0, "annual_budget_INR": 0, "has_mission_defined": true, "legal_registration_completed": false}', '{"legal_registration_completed": true, "theory_of_change_draft_exists": true, "first_grant_or_donation_received": true}', 'NGO Stage 1 (Ideation): Mission defined but organisation not yet registered. Exit when legal registration is complete, first funding received, and a Theory of Change draft exists.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('26', '4', '2', '{"active_donors_min": 1, "annual_budget_INR_min": 100000, "legal_registration_completed": true, "theory_of_change_draft_exists": true}', '{"active_donors_min": 3, "programme_running": true, "annual_budget_INR_max": 3000000}', 'NGO Stage 2 (Validation): Registered, first funding in, draft ToC exists. Exit when annual budget crosses Rs 3L with at least 3 donors and at least one active programme running with measurable beneficiaries.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('27', '4', '3', '{"funding_stage": "grants or CSR or individual donors", "active_donors_min": 3, "programme_running": true, "annual_budget_INR_min": 3000000}', '{"annual_budget_INR_max": 10000000, "impact_metrics_tracked": true, "programme_expense_ratio_min_pct": 60}', 'NGO Stage 3 (Prototype/MVP): Annual budget Rs 3L to Rs 1 Crore. At least one programme delivering measurable impact. Programme expense ratio above 60%. Impact metrics being tracked systematically.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('28', '4', '4', '{"active_donors_min": 5, "annual_budget_INR_min": 10000000, "impact_metrics_tracked": true, "operating_reserve_months_min": 2, "programme_expense_ratio_min_pct": 60}', '{"annual_budget_INR_max": 50000000, "earned_revenue_exists": true, "single_donor_concentration_max_pct": 50}', 'NGO Stage 4 (Early Traction): Annual budget Rs 1 Crore to Rs 5 Crore. No single donor above 50% of budget. First earned revenue stream initiated. 2+ months operating reserve maintained.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('29', '4', '5', '{"annual_budget_INR_min": 50000000, "earned_revenue_pct_min": 10, "operating_reserve_months_min": 3, "programme_expense_ratio_min_pct": 65, "single_donor_concentration_max_pct": 50}', '{"annual_budget_INR_max": 200000000, "earned_revenue_pct_min": 20, "fcra_registered_if_foreign_funding": true}', 'NGO Stage 5 (Growth/Scaling): Annual budget Rs 5 Crore to Rs 20 Crore. Earned revenue above 20% of total budget. FCRA registration in place if receiving foreign funding. 3+ months operating reserve.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('30', '4', '6', '{"annual_budget_INR_min": 200000000, "earned_revenue_pct_min": 20, "has_professional_management": true, "fcra_registered_if_foreign_funding": true}', '{"annual_budget_INR_max": 1000000000, "impact_audit_completed": true, "geographic_expansion_min_states": 3}', 'NGO Stage 6 (Expansion): Annual budget Rs 20 Crore to Rs 100 Crore. Operating across 3+ states. Professional CEO or ED in place. Third-party impact audit completed.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('31', '4', '7', '{"annual_budget_INR_min": 1000000000, "earned_revenue_pct_min": 25, "impact_audit_completed": true, "has_governance_structure": true, "geographic_expansion_min_states": 3}', '{"succession_plan_documented": true, "institutional_independence_achieved": true}', 'NGO Stage 7 (Maturity): Annual budget Rs 100 Crore and above. Strong governance, diversified funding, 25%+ earned revenue. Succession plan documented. Organisation can operate independently of founder.') on conflict do nothing;
insert into "industry_stage_thresholds" ("threshold_id", "industry_id", "stage_id", "stage_entry_criteria", "stage_exit_criteria", "notes") values ('32', '4', '8', '{"succession_plan_documented": true, "founder_transition_initiated": true, "institutional_independence_achieved": true}', '{"founder_transition_completed": true}', 'NGO Stage 8 (Exit/Legacy): Founder formally transitioning out of leadership. Succession in place. Organisation independent of founder personal relationships and involvement.') on conflict do nothing;
